import{_ as s}from"./chunks/datacopy_gm2l1_nd2nz_copy.BIvYdbkN.js";import{_ as n,o as t,a as p,b as l}from"./app.C41L12d5.js";const c="/ascendc.github.io/assets/datacopy_gm2l1_nd2nz_continuous_copy.Duui7SSQ.png",i="/ascendc.github.io/assets/datacopy_gm2l1_nd2nz_noncontinuous_copy.BGoDvlre.png",e="/ascendc.github.io/assets/nd2nz_small_c0_half.Bvj3jOlu.png",d="/ascendc.github.io/assets/datacopy_gm2l1_nd2nz_demo.DUHsPAfM.png",v=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵计算的搬入","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/cube_compute_load"},{"text":"DataCopy（GMToL1随路转换-ND2NZ搬运）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/DataCopy_GMToL1_ND2NZ"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/DataCopy_GMToL1_ND2NZ.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/DataCopy_GMToL1_ND2NZ.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":3,"title":"enableSmallC0参数支持度说明","slug":"enableSmallC0参数支持度说明","link":"#enableSmallC0参数支持度说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"关键特性说明","slug":"关键特性说明","link":"#关键特性说明"},{"level":3,"title":"连续搬运","slug":"连续搬运","link":"#连续搬运"},{"level":3,"title":"非连续搬运","slug":"非连续搬运","link":"#非连续搬运"},{"level":3,"title":"SmallC0模式","slug":"SmallC0模式","link":"#SmallC0模式"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),r={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/DataCopy_GMToL1_ND2NZ.md"};function o(_,a,h,u,N,m){return t(),p("div",null,[...a[0]||(a[0]=[l('<div><article class="markdown-body"><h1>DataCopy（GMToL1随路转换-ND2NZ搬运）<a id="ZH-CN_TOPIC_0000002569070913"></a></h1><h2 id="产品支持情况">产品支持情况<a id="zh-cn_topic_0000002566538879_section796754519912"></a><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：支持</li></ul></div><h2 id="功能说明">功能说明<a id="zh-cn_topic_0000002566538879_section106841136114319"></a><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_data_copy_intf.h&quot;</code>。</p><p>该接口主要实现将矩阵从Global Memory搬运至L1 Buffer（TPosition为A1/B1），并支持在数据搬运时进行ND到NZ格式的转换。</p><p>ND到NZ的格式转换等价于DN到ZN的格式转换，如<a href="#zh-cn_topic_0000002566538879_fig444462417355">图1</a>。</p><p><strong>图1</strong> ND2NZ与DN2ZN示意图<a id="zh-cn_topic_0000002566538879_fig444462417355"></a></p><p><img src="'+s+`" alt></p><h2 id="函数原型">函数原型<a id="zh-cn_topic_0000002566538879_section82039854412"></a><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">DataCopy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">Nd2NzParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">intriParams</span><span class="p">)</span>
</code></pre></div><div data-filter="950"><p>特别针对Ascend 950PR/Ascend 950DT，函数原型请参考如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="kt">bool</span><span class="w"> </span><span class="n">enableSmallC0</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">false</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">DataCopy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">Nd2NzParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">intriParams</span><span class="p">)</span>
</code></pre></div></div><h2 id="参数说明">参数说明<a id="zh-cn_topic_0000002566538879_section16128134420472"></a><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>源操作数或者目的操作数的数据类型。支持的数据类型请参考<a href="#zh-cn_topic_0000002566538879_section4219135304818">数据类型</a>。</td></tr><tr><td>enableSmallC0</td><td>SmallC0模式开关：当dValue小于等于4的时候，C0_SIZE会补齐到4 * sizeof(T)字节。<br>默认不开启。不同的型号，enableSmallC0支持度不同，请参考<a href="#enablesmallc0%E5%8F%82%E6%95%B0%E6%94%AF%E6%8C%81%E5%BA%A6%E8%AF%B4%E6%98%8E">enableSmallC0参数支持度说明</a>。</td></tr></tbody></table><h3 id="enableSmallC0参数支持度说明">enableSmallC0参数支持度说明<a class="header-anchor" href="#enableSmallC0参数支持度说明">​</a></h3><div data-filter="950"><ul><li>针对Ascend 950PR/Ascend 950DT，新增enableSmallC0参数，调用该接口必须配置参数enableSmallC0；</li></ul></div><ul><li>其他型号不支持该参数。</li></ul><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，类型为LocalTensor，存储位置为L1 Buffer（TPosition为A1/B1），目的地址需要32字节对齐。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，类型为GlobalTensor，存储位置为Global Memory，源地址需要1字节对齐。</td></tr><tr><td>intriParams</td><td>输入</td><td>ND2NZ搬运参数，类型为Nd2NzParams。<br>Nd2NzParams参数说明请参考<a href="#zh-cn_topic_0000002566538879_table144203616291">表4</a>。</td></tr></tbody></table><p><strong>表3</strong> Nd2NzParams结构体参数定义<a id="zh-cn_topic_0000002566538879_table144203616291"></a></p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>ndNum</td><td>源矩阵中ND矩阵的数量，取值范围：ndNum∈[0, 4095]。<br><strong>注：ndNum = 0表示不执行搬运，该接口将被视为NOP（空操作）。</strong></td></tr><tr><td>nValue</td><td>源矩阵中ND矩阵的行数，取值范围：nValue∈[0, 16384]。<br><strong>注：nValue = 0表示不执行搬运，该接口将被视为NOP（空操作）。</strong></td></tr><tr><td>dValue</td><td>源矩阵中ND矩阵的列数，取值范围：dValue∈[0, 65535]。当dValue * sizeof(T)不满足32字节对齐时，在目的矩阵中会补0对齐到32字节。<br><strong>注：dValue = 0表示不执行搬运，该接口将被视为NOP（空操作）。</strong></td></tr><tr><td>srcNdMatrixStride</td><td>源矩阵相邻ND矩阵起始地址间的偏移，取值范围：srcNdMatrixStride∈[0, 65535]，单位：元素个数。<br>  • ndNum = 1时，srcNdMatrixStride无意义，设置为0即可。<br>  • ndNum ≠ 1时，当srcNdMatrixStride = 0时，表示重复搬出源矩阵的第一个ND矩阵。</td></tr><tr><td>srcDValue</td><td>源矩阵一行中包含的元素个数，取值范围：srcDValue∈[1, 65535]，单位：元素个数。</td></tr><tr><td>dstNzC0Stride</td><td>ND转换为NZ格式后，目的NZ矩阵中相邻Z矩阵起始地址的偏移，取值范围：dstNzC0Stride∈[1, 16384]，单位：C0_SIZE（32字节）。</td></tr><tr><td>dstNzNStride</td><td>目的矩阵中，NZ矩阵中相邻行起始地址的偏移，取值范围：dstNzNStride∈[1, 16384]，单位：C0_SIZE（32字节）。</td></tr><tr><td>dstNzMatrixStride</td><td>目的矩阵中，相邻NZ矩阵起始地址的偏移，取值范围：dstNzMatrixStride∈[0, 16384]，单位：元素个数。<br>  • ndNum = 1时，dstNzMatrixStride无意义，设置为0即可。<br>  • ndNum ≠ 1时，当dstNzMatrixStride = 0时，表示目的矩阵中搬入的每个NZ矩阵都会覆盖第一个NZ矩阵。</td></tr></tbody></table><h2 id="数据类型">数据类型<a id="zh-cn_topic_0000002566538879_section4219135304818"></a><a class="header-anchor" href="#数据类型">​</a></h2><p>源矩阵和目的矩阵支持的数据类型保持一致。</p><div data-filter="950"><p>针对Ascend 950PR/Ascend 950DT，支持的数据类型为：bool、int8_t、uint8_t、fp4x2_e2m1_t、fp4x2_e1m2_t、hifloat8_t、fp8_e5m2_t、fp8_e4m3fn_t、fp8_e8m0_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、complex32。</p></div><div data-filter="A3"><p>针对Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持数据类型为：b4（int4b_t）、int8_t、uint8_t、int16_t、uint16_t、int32_t、uint32_t、half、bfloat16_t、float。</p></div><div data-filter="910b"><p>针对Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持数据类型为：b4（int4b_t）、int8_t、uint8_t、int16_t、uint16_t、int32_t、uint32_t、half、bfloat16_t、float。</p></div><div data-filter="310p"><p>针对Atlas 推理系列产品AI Core，支持数据类型为：int16_t、uint16_t、int32_t、uint32_t、half、float。</p></div><div data-filter="x90"><p>Kirin X90，支持数据类型为：int8_t、uint8_t、int16_t、uint16_t、half。</p></div><div data-filter="9030"><p>Kirin 9030，支持数据类型为：int8_t、uint8_t、int16_t、uint16_t、half。</p></div><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a id="zh-cn_topic_0000002566538879_section2045914466492"></a><a class="header-anchor" href="#约束说明">​</a></h2><ul><li><p>当输入数据类型是b4时，ND2NZ过程中数据是基于b8类型进行处理，因此参数需要根据b8类型进行设置。</p></li><li><p>位于Global Memory的源地址必须1字节对齐，位于L1 Buffer的目的地址必须32字节对齐。</p></li><li><p>当Nd2NzParams结构体参数ndNum、nValue、dValue任意一个值为0时，该指令不会执行，该接口将被视为NOP（空操作）。</p></li><li><p>搬运至L1 Buffer的数据不能重叠，如果存在重叠写入，硬件不会产生任何警告或错误，并且不保证重叠数据的写入顺序。</p></li><li><p>Nd2NzParams结构体参数的值需在取值范围内：</p><p><strong>表4</strong> Nd2NzParams结构体参数取值范围</p><table><thead><tr><th>参数名称</th><th>取值范围</th></tr></thead><tbody><tr><td>ndNum</td><td>[0, 4095]</td></tr><tr><td>nValue</td><td>[0, 16384]</td></tr><tr><td>dValue</td><td>[0, 65535]</td></tr><tr><td>srcNdMatrixStride</td><td>[0, 65535]</td></tr><tr><td>srcDValue</td><td>[1, 65535]</td></tr><tr><td>dstNzC0Stride</td><td>[1, 16384]</td></tr><tr><td>dstNzNStride</td><td>[1, 16384]</td></tr><tr><td>dstNzMatrixStride</td><td>[0, 16384]</td></tr></tbody></table></li></ul><div data-filter="310p"><ul><li>针对Atlas 推理系列产品AI Core，使用Global Memory -&gt; Local Memory通路的ND2NZ搬运接口时，需要预留8K的Unified Buffer（UB）空间，作为接口的临时数据存放区。</li></ul></div><h2 id="关键特性说明">关键特性说明<a class="header-anchor" href="#关键特性说明">​</a></h2><h3 id="连续搬运">连续搬运<a id="zh-cn_topic_0000002566538879_section7495192151713"></a><a class="header-anchor" href="#连续搬运">​</a></h3><p>以half数据类型为例，<a href="#zh-cn_topic_0000002566538879_fig7420114233419">图2</a>为ND2NZ连续搬运示意图。Nd2NzParams结构体参数配置说明如下：</p><ul><li>ndNum = 1，表示搬运的ND矩阵的数量为1。</li><li>nValue = 16，一个ND矩阵的行数。</li><li>dValue = 23，一个ND矩阵的列数。当dValue * sizeof(T)不满足32字节对齐时，在目的矩阵中会补0对齐到32字节。</li><li>srcNdMatrixStride = 0，只有一个ND矩阵，该值为0。</li><li>srcDValue = 32，表示源矩阵一行所含元素个数，即32个half数据类型的元素。</li><li>dstNzC0Stride = 16，NZ矩阵中相邻Z矩阵起始地址的偏移，偏移为16个C0_SIZE。</li><li>dstNzNStride = 1，表示NZ矩阵中相邻行起始地址的偏移。</li><li>dstNzMatrixStride = 0，只有一个NZ矩阵，该值为0。</li></ul><p><strong>图2</strong> ND2NZ转换示意图（连续搬运）<a id="zh-cn_topic_0000002566538879_fig7420114233419"></a></p><p><img src="`+c+'" alt></p><h3 id="非连续搬运">非连续搬运<a id="zh-cn_topic_0000002566538879_section1721231581717"></a><a class="header-anchor" href="#非连续搬运">​</a></h3><p>以half数据类型为例，<a href="#zh-cn_topic_0000002566538879_fig19978184883316">图3</a>为ND2NZ非连续搬运示意图。Nd2NzParams结构体参数配置说明如下：</p><ul><li>ndNum = 2，表示搬运的ND矩阵的数量为2。</li><li>nValue = 8，一个ND矩阵的行数。</li><li>dValue = 23，一个ND矩阵的列数。当dValue * sizeof(T)不满足32字节对齐时，在目的矩阵中会补0对齐到32字节。</li><li>srcNdMatrixStride = 384，表示相邻ND矩阵起始地址的偏移，每行32个元素，共12行，偏移为32 * 12 = 384个元素。</li><li>srcDValue = 32，表示源矩阵一行所含元素个数，即32个half数据类型的元素。</li><li>dstNzC0Stride = 37，NZ矩阵中相邻Z矩阵起始地址的偏移，偏移为37个C0_SIZE。</li><li>dstNzNStride = 2，表示NZ矩阵中相邻行起始地址的偏移。</li><li>dstNzMatrixStride = 320，相邻NZ矩阵起始地址的偏移，每行16个元素，共20行，偏移为16 * 20 = 320个元素。</li></ul><p><strong>图3</strong> ND2NZ转换示意图（非连续搬运）<a id="zh-cn_topic_0000002566538879_fig19978184883316"></a></p><p><img src="'+i+'" alt></p><h3 id="SmallC0模式">SmallC0模式<a class="header-anchor" href="#SmallC0模式">​</a></h3><p>enableSmallC0开启模式下的ND2NZ转换示意图如下：</p><p><strong>图4</strong> enableSmallC0开启模式下的ND2NZ转换示意图（half数据类型）<span id="fig07641913195410"></span></p><p><img src="'+e+'" alt title="enableSmallC0开启模式下的ND2NZ转换示意图-（half数据类型）"></p><h2 id="调用示例">调用示例<a id="zh-cn_topic_0000002566538879_section088124295117"></a><a class="header-anchor" href="#调用示例">​</a></h2><p>如下示例中：在A矩阵不转置，数据类型为half的场景下，使用DataCopy进行随路ND2NZ数据搬运。</p><p>搬运过程的数据排布变化示意图如下：</p><p><img src="'+d+`" alt></p><p>示例代码片段如下，仅展示样例中的部分代码，完整示例请参考：<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_basic_api/03_matrix_compute/load_data_l12l0">DataCopy_GM2L1样例</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// m=40,k=56,fractalShape[0] = 16,fractalShape[1] = 16,fractalSize = 16 * fractalShape[1]</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Nd2NzParams</span><span class="w"> </span><span class="n">nd2nzA1Params</span><span class="p">;</span>
<span class="c1">// 传输ND矩阵的数目</span>
<span class="n">nd2nzA1Params</span><span class="p">.</span><span class="n">ndNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="c1">// ND矩阵的行数</span>
<span class="n">nd2nzA1Params</span><span class="p">.</span><span class="n">nValue</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">m</span><span class="p">;</span>
<span class="c1">// ND矩阵的列数</span>
<span class="n">nd2nzA1Params</span><span class="p">.</span><span class="n">dValue</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">k</span><span class="p">;</span>
<span class="c1">// 只传输了1个ND矩阵，该参数无效</span>
<span class="n">nd2nzA1Params</span><span class="p">.</span><span class="n">srcNdMatrixStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="c1">// 源矩阵一行中包含的元素个数</span>
<span class="n">nd2nzA1Params</span><span class="p">.</span><span class="n">srcDValue</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">k</span><span class="p">;</span>
<span class="c1">// 以下这个参数取A矩阵在L1 Buffer上，高度方向的对齐后的长度</span>
<span class="n">nd2nzA1Params</span><span class="p">.</span><span class="n">dstNzC0Stride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">CeilAlign</span><span class="p">(</span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">fractalShape</span><span class="p">[</span><span class="mi">0</span><span class="p">]);</span>
<span class="n">nd2nzA1Params</span><span class="p">.</span><span class="n">dstNzNStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="n">nd2nzA1Params</span><span class="p">.</span><span class="n">dstNzMatrixStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">a1Local</span><span class="p">,</span><span class="w"> </span><span class="n">aGM</span><span class="p">,</span><span class="w"> </span><span class="n">nd2nzA1Params</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const A=n(r,[["render",o]]);export{v as __pageData,A as default};
